/// The filter's error constant: E · (1 + 2u)^3 with E = 28u + 52u^2 + 48u^3 + 22u^4 + 4u^5, the
/// result's unit error (header), rounded up to an `f64`: 7881299347898375 · 2^-101.
const ERROR: f64 = f64::from_bits(0x3cec_0000_0000_0007);

/// `orient3d`'s sign from its `f64` filter, or `None` when the filter's bound cannot certify it.
///
/// `Some(Sign::Zero)` only when the scale is zero, which makes the exact value zero.
#[inline]
#[must_use]
#[allow(
    clippy::similar_names,
    reason = "each name is a step of the description, named by the language's rule"
)]
pub fn filter(a: P3, b: P3, c: P3, d: P3) -> Option<Sign> {
    let ba_x = exact_f64(b.x) - exact_f64(a.x);
    let ba_y = exact_f64(b.y) - exact_f64(a.y);
    let ba_z = exact_f64(b.z) - exact_f64(a.z);
    let ca_x = exact_f64(c.x) - exact_f64(a.x);
    let ca_y = exact_f64(c.y) - exact_f64(a.y);
    let ca_z = exact_f64(c.z) - exact_f64(a.z);
    let da_x = exact_f64(d.x) - exact_f64(a.x);
    let da_y = exact_f64(d.y) - exact_f64(a.y);
    let da_z = exact_f64(d.z) - exact_f64(a.z);
    let n_x_1 = ca_y * da_z;
    let n_x_2 = ca_z * da_y;
    let n_x = n_x_1 - n_x_2;
    let n_y_1 = ca_z * da_x;
    let n_y_2 = ca_x * da_z;
    let n_y = n_y_1 - n_y_2;
    let n_z_1 = ca_x * da_y;
    let n_z_2 = ca_y * da_x;
    let n_z = n_z_1 - n_z_2;
    let det_1 = ba_x * n_x;
    let det_2 = ba_y * n_y;
    let det_3 = det_1 + det_2;
    let det_4 = ba_z * n_z;
    let det = det_3 + det_4;
    let m_x = largest_magnitude([ba_x, ca_x, da_x]);
    let m_y = largest_magnitude([ba_y, ca_y, da_y]);
    let m_z = largest_magnitude([ba_z, ca_z, da_z]);
    let scale = m_x * m_y * m_z;
    decide(det, ERROR, scale)
}

/// `orient3d`'s exact value: each step in the type its certificate gives it, with checked
/// arithmetic; `None` only if a step overflowed, which the certificate rules out.
#[inline]
#[must_use]
#[allow(
    clippy::similar_names,
    reason = "each name is a step of the description, named by the language's rule"
)]
pub fn value(a: P3, b: P3, c: P3, d: P3) -> Option<i128> {
    let ba_x = b.x.get().checked_sub(a.x.get())?;
    let ba_y = b.y.get().checked_sub(a.y.get())?;
    let ba_z = b.z.get().checked_sub(a.z.get())?;
    let ca_x = c.x.get().checked_sub(a.x.get())?;
    let ca_y = c.y.get().checked_sub(a.y.get())?;
    let ca_z = c.z.get().checked_sub(a.z.get())?;
    let da_x = d.x.get().checked_sub(a.x.get())?;
    let da_y = d.y.get().checked_sub(a.y.get())?;
    let da_z = d.z.get().checked_sub(a.z.get())?;
    let n_x_1 = i128::from(ca_y).checked_mul(i128::from(da_z))?;
    let n_x_2 = i128::from(ca_z).checked_mul(i128::from(da_y))?;
    let n_x = n_x_1.checked_sub(n_x_2)?;
    let n_y_1 = i128::from(ca_z).checked_mul(i128::from(da_x))?;
    let n_y_2 = i128::from(ca_x).checked_mul(i128::from(da_z))?;
    let n_y = n_y_1.checked_sub(n_y_2)?;
    let n_z_1 = i128::from(ca_x).checked_mul(i128::from(da_y))?;
    let n_z_2 = i128::from(ca_y).checked_mul(i128::from(da_x))?;
    let n_z = n_z_1.checked_sub(n_z_2)?;
    let det_1 = i128::from(ba_x).checked_mul(n_x)?;
    let det_2 = i128::from(ba_y).checked_mul(n_y)?;
    let det_3 = det_1.checked_add(det_2)?;
    let det_4 = i128::from(ba_z).checked_mul(n_z)?;
    let det = det_3.checked_add(det_4)?;
    Some(det)
}

/// `orient3d`'s exact sign: the sign of [`value`], or `None` as for [`value`].
#[inline]
#[must_use]
pub fn exact(a: P3, b: P3, c: P3, d: P3) -> Option<Sign> {
    value(a, b, c, d).map(Sign::of_i128)
}
